using System;using System.IO;using System.Linq;using System.Collections.Generic;using Frociart;
internal static class PostTestPlanTests {
 static int checks;static void Check(bool value,string why){checks++;if(!value)throw new Exception(why);}
 static int Repeats(IEnumerable<FlowSourcePlan.Statement> statements){return statements.Sum(s=>(s.Kind.ToString()=="Repeat"?1:0)+Repeats(s.Body)+Repeats(s.Otherwise));}
 static void Case(string root,string name,string text,int repeats,bool invert=false){var d=FlowPseudocode.Decode(text);if(invert){var tail=d.Nodes.Last(n=>n.Kind==NodeKind.Decision);tail.Text="not ("+tail.Text+")";foreach(var edge in d.Edges.Where(e=>e.From==tail.Id))edge.Branch=edge.Branch=="true"?"false":"true";}byte[] before=DiagramIO.EncodeDocument(d);var p=FlowSource.Compile(d);Check(p.CanGenerate,name+" compiles");int count=0;foreach(var scope in p.Scopes){var plan=FlowSourcePlan.Create(scope);Check(plan.Structured,name+" retains structured source");count+=Repeats(plan.Statements);}Check(count==repeats,name+" recognizes every post-test loop");Directory.CreateDirectory(Path.Combine(root,"fixtures"));File.WriteAllBytes(Path.Combine(root,"fixtures",name+".frociart"),before);foreach(var target in FlowSourceTarget.All){var source=target.Generate(p);Check(!source.Text.Contains("Collegamenti espliciti per conservare questo grafo"),name+" readable "+target.Id);foreach(var scope in p.Scopes)foreach(var block in scope.Blocks)Check(source.ForBlock(scope.Id,block.Id).Count>0,name+" mapped "+target.Id);File.WriteAllText(Path.Combine(root,name+"."+target.Extension),source.Text);}Check(before.SequenceEqual(DiagramIO.EncodeDocument(d)),name+" does not edit diagram");}
 static int Main(string[] args){try{string r=args[0];Case(r,"repeat-once","x=5\nRIPETI\nx=x+1\nFINCHE x > 0\nSTAMPA x",1);Case(r,"repeat-branch","x=0\nRIPETI\nSE x % 2 == 0 ALLORA\nx=x+1\nALTRIMENTI\nx=x+2\nFINE SE\nFINCHE x>=5\nSTAMPA x",1);Case(r,"repeat-nested","x=0\nRIPETI\nRIPETI\nx=x+1\nFINCHE x % 3 == 0\nFINCHE x>=9\nSTAMPA x",2);Case(r,"repeat-in-while","x=0\nMENTRE x<8 FAI\nRIPETI\nx=x+1\nFINCHE x % 2 == 0\nFINE MENTRE\nSTAMPA x",1);Case(r,"while-in-repeat","x=0\nRIPETI\nMENTRE x<3 FAI\nx=x+1\nFINE MENTRE\nx=x+1\nFINCHE x>=7\nSTAMPA x",1);Case(r,"repeat-function","FUNZIONE conta() -> INTERO risultato\nrisultato=0\nRIPETI\nrisultato=risultato+1\nFINCHE risultato>=3\nFINE FUNZIONE\nSTAMPA conta()",1);Case(r,"repeat-call-condition","FUNZIONE pronto(x: INTERO) -> LOGICO risultato\nSTAMPA x\nrisultato=x>=3\nFINE FUNZIONE\nx=0\nRIPETI\nx=x+1\nFINCHE pronto(x)\nSTAMPA x",1);Case(r,"repeat-reference-condition","FUNZIONE pronto(a: RIF INTERO[]) -> LOGICO risultato\na[0]=a[0]+1\nrisultato=a[0]>=3\nFINE FUNZIONE\na=[0]\nRIPETI\nSTAMPA a[0]\nFINCHE pronto(a)\nSTAMPA a",1);Case(r,"repeat-continued-output","x=0\nRIPETI\nSTAMPA_CONTINUA x\nx=x+1\nFINCHE x>=3\nSTAMPA \" Fine\"",1);Case(r,"repeat-body-error","x=0\nRIPETI\nSTAMPA 1 / x\nFINCHE vero",1);Case(r,"repeat-condition-error","x=0\nRIPETI\nx=x+1\nFINCHE 1 / 0 > 0",1);Case(r,"repeat-turtle","x=0\nRIPETI\nAVANZA 10\nRUOTA DESTRA 90\nx=x+1\nFINCHE x>=4\nSTAMPA x",1);Case(r,"repeat-true-branch","x=0\nRIPETI\nx=x+1\nFINCHE x>=3\nSTAMPA x",1,true);Case(r,"repeat-input","x=0\nRIPETI\nLEGGI x\nFINCHE x>=0\nSTAMPA x",1);Case(r,"nested-while-join","x=0\nMENTRE x<1 FAI\nMENTRE x<5 FAI\nSE x>4 ALLORA\nx=x+1\nALTRIMENTI\nx=x+1\nFINE SE\nFINE MENTRE\nFINE MENTRE\nSTAMPA x",0);Case(r,"repeat-shared-while-header","x=0\nRIPETI\nMENTRE x<5 FAI\nMENTRE x<5 FAI\nx=x+1\nFINE MENTRE\nFINE MENTRE\nFINCHE x>=3\nSTAMPA x",1);Console.WriteLine("POST_TEST_PLAN PASS checks="+checks);return 0;}catch(Exception e){Console.WriteLine(e);return 1;}}
}
